<original_code>
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
using namespace std;

vector<int> adj[2020];
int ir[20][20];
int sc[20][20];
int pc[20][20];
char s[20][20];
char p[20][20];
int dd[20][20];
int dx[5] = {0, 1, -1, 0};
int dy[5] = {1, 0, 0, -1};
vector<int> srcNodes[20][20], tgtNodes[20][20];

void addEdge(int a, int b) {
    adj[a].push_back(b);
    adj[b].push_back(a);
}

int dist[2020];
int match[2020];
int leftCnt, rightStart;

bool bfsHK() {
    deque<int> q;
    for (int i = 1; i <= leftCnt; ++i) {
        if (match[i] == 0) {
            dist[i] = 0;
            q.push_back(i);
        } else {
            dist[i] = 3010;
        }
    }
    dist[0] = 3010;
    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        if (dist[u] < dist[0]) {
            for (int v : adj[u]) {
                int w = match[v];
                if (dist[w] > dist[u] + 1) {
                    dist[w] = dist[u] + 1;
                    q.push_back(w);
                }
            }
        }
    }
    return dist[0] != 3010;
}

bool dfsHK(int x) {
    if (x == 0) return true;
    for (int v : adj[x]) {
        int u = match[v];
        if (dist[u] == dist[x] + 1) {
            if (dfsHK(u)) {
                match[x] = v;
                match[v] = x;
                return true;
            }
        }
    }
    return false;
}

int hopcroftKarp() {
    int res = 0;
    while (bfsHK()) {
        for (int i = 1; i <= leftCnt; ++i) {
            if (match[i] == 0) {
                res += dfsHK(i);
            }
        }
    }
    return res;
}

int n, t;

void processCell(int a, int b) {
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            dd[i][j] = 100000;
    deque<pair<int,int>> q;
    dd[a][b] = 0;
    q.push_back({a, b});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop_front();
        for (int v : tgtNodes[x][y])
            for (int u : srcNodes[a][b])
                addEdge(u, v);
        if (dd[x][y] == ir[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (sc[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= ir[nx][ny]) {
                dd[nx][ny] = dd[x][y] + 1;
                q.push_back({nx, ny});
            }
        }
    }
}

int main() {
    cin >> n >> t;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            ir[i][j] = t;
    for (int i = 1; i <= n; ++i)
        cin >> (s[i] + 1);
    for (int i = 1; i <= n; ++i)
        cin >> (p[i] + 1);
    int rx, ry;
    leftCnt = 1;
    rightStart = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i][j] == 'Z' || s[i][j] == 'Y') {
                sc[i][j] = -1;
                ir[i][j] = 0;
            }
            if (s[i][j] == 'Z') {
                rx = i; ry = j;
                ir[i][j] = 0;
            }
            if (s[i][j] >= '0' && s[i][j] <= '9')
                sc[i][j] = s[i][j] - '0';
            for (int k = 0; k < sc[i][j]; ++k)
                srcNodes[i][j].push_back(leftCnt++);
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (p[i][j] >= '0' && p[i][j] <= '9')
                pc[i][j] = p[i][j] - '0';
            for (int k = 0; k < pc[i][j]; ++k)
                tgtNodes[i][j].push_back(rightStart++);
        }
    }
    deque<pair<int,int>> q;
    q.push_back({rx, ry});
    while (!q.empty()) {
        rx = q.front().first; ry = q.front().second;
        q.pop_front();
        for (int d = 0; d < 4; ++d) {
            int nx = rx + dx[d], ny = ry + dy[d];
            if (ir[nx][ny] > ir[rx][ry] + 1 && sc[nx][ny] != -1) {
                ir[nx][ny] = ir[rx][ry] + 1;
                q.push_back({nx, ny});
            }
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sc[i][j] > 0)
                processCell(i, j);
    cout << hopcroftKarp() << endl;
    return 0;
}
